      c('Попросить Константина обещать не жертвовать собой без согласия группы.', 'c5_11',{closeness:1,trust:1},{konNoSacrificePromise:true}),
      c('Попросить Елену взять ответственность за каждый шаг.', 'c5_11',{resolve:1},{elenaTakesResponsibility:true})
